render=function(){if(section==='launch'){portalRender();return}section='review';nav();$('#main').innerHTML=`<div class="systemtabs"><span onclick="section='launch';render()">首页</span><span class="selected">● 接入登记审核 ×</span></div><div class="registration-page"><section class="panel querypanel" ${req('node.query')}><div class="querygrid">${['业务节点登记名称','业务节点标识','状态','统一社会信用代码','所属法人或组织名称','所属法人身份标识'].map((n,i)=>`<label>${n}${i===2?'<select id="state"><option>请选择</option><option>待人工审核</option></select>':`<input id="${i===0?'search':'filter-'+i}" placeholder="请输入">`}</label>`).join('')}</div><div class="queryactions"><button class="btn primary" onclick="drawRows()">⌕ 查询</button><button class="btn" onclick="document.querySelectorAll('.querygrid input').forEach(e=>e.value='');$('#state').selectedIndex=0;drawRows()">↻ 重置</button></div></section><section class="panel listpanel"><div class="listtools"><button class="btn" ${req('node.create')} onclick="openForm()">＋ 新增</button><button class="btn" onclick="toast('请使用新增功能填写接入登记')">↥ 批量导入</button><button class="btn" onclick="toast('标识使用默认蓝色胶囊样式')">⚑ 调整标识样式</button><button class="btn riskpreview" ${req('node.riskPreview')} onclick="previewRisk()">查看敏感词审核不通过页面</button><span style="margin-left:auto;color:#98a5b6">↻　⊞</span></div><table><thead><tr>${['业务节点登记名称','业务节点标识','所属法人或其他组织名称','所属法人身份标识','统一社会信用代码','操作'].map(n=>'<th>'+n+'</th>').join('')}</tr></thead><tbody id="rows"></tbody></table><div class="pagination" id="pagination"></div></section></div>`;drawRows()};
const examples=['浪潮工互可信空间','浪潮工互可信空间…','https://tds.inspurip…','医保行业可信数据…','可信数据空间平台','[test]测试业务节点2…','重庆可信数据空间'];
drawRows=function(){if(!$('#rows'))return;const query=$('#search').value;const list=[...rows.map(r=>({...r,newRecord:true})),...examples.map((name,i)=>({name,org:i===5?'测试企业':i===4?'可信重庆':'惠医云（重庆）数…',identifier:[0,3,5,6].includes(i)?'491370782MAC5R7KD3J5000VLl0T29VF':'-',version:'v1.0.0',description:'示例登记，仅用于界面展示'}))].filter(r=>r.name.includes(query)&&($('#state').selectedIndex!==1||r.newRecord));$('#rows').innerHTML=list.length?list.map((r,i)=>`<tr><td>${esc(r.name)}${r.newRecord?'<small class="newstate">待人工审核</small>':''}</td><td><span class="identifier">${r.newRecord?'待分配':r.identifier}</span></td><td>${esc(r.org)}</td><td>91370782MAC5R7…</td><td>91370782MAC5R7…</td><td>${r.newRecord?'<span class="status ok">机器审核通过</span>':`<button class="link" onclick="toast('示例记录，仅展示登记状态')">${i%3===0?'♧ 登记更新　♜ 注销　更多⌄':'⟳ 重新提交　⊙ 详情'}</button>`}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">暂无匹配记录</td></tr>';$('#pagination').innerHTML=`共 ${list.length} 条　　10条/页　　〈 <b>1</b> 〉　 前往　1　页`};
const baseAudit=showAudit;
showAudit=function(state){if(state!=='risk'){baseAudit(state);return}let layer=$('#audit');if(!layer){layer=document.createElement('div');layer.id='audit';layer.className='veil';document.body.append(layer)}layer.style.zIndex=30;const demo=auditScenario==='risk';const text=pending?.description||'';const hits=[['敏感词','业务简介','敏感词测试','请删除敏感表述，使用准确、客观的业务说明。'],['涉黄内容','业务简介','涉黄测试','请删除色情、低俗或性暗示相关内容。'],['涉暴内容','业务简介','涉暴测试','请删除暴力、威胁或煽动伤害相关内容。']].filter(r=>(demo&&r[0]==='敏感词')||text.includes(r[2])||(pending?.remark||'').includes(r[2]));layer.innerHTML=`<section class="riskdialog" ${req('node.machineAudit')}><div class="riskhead"><span class="riskshield">!</span><div><span class="riskcaption">内容安全审核结果</span><h2>敏感词审核未通过</h2><p>业务简介中存在敏感内容，请修改后重新提交审核。</p></div><button class="close" onclick="finishAudit('risk')">×</button></div><div class="riskbody"><div class="risknotice">⊗ 本次申请未提交成功，不会进入人工审核队列。已填写的信息和已选材料将保留。</div><div class="risksectiontitle"><h3>风险明细 <span>${hits.length} 项</span></h3><span>请逐项检查并修改</span></div><table class="risktable"><thead><tr><th>风险类型</th><th>命中位置</th><th>命中内容 / 证据</th><th>修改建议</th></tr></thead><tbody>${hits.map((r,i)=>`<tr><td><span class="riskbadge">${r[0]}</span></td><td>${(pending?.remark||'').includes(r[2])?'备注':r[1]}</td><td><span class="excerpt">… <mark>${r[2]}</mark> …</span></td><td>${r[3]}</td></tr>`).join('')}</tbody></table><div class="riskhelp"><b>如何完成提交？</b><p>修改命中的文本或替换不合规材料，再点击「提交审核」。系统将重新进行机器审核，通过后才进入人工审核。</p></div><details class="auditscope"><summary>查看敏感内容分类</summary><p><b>敏感内容：</b>色情招揽、露骨色情描述；暴力威胁、煽动伤害；定向辱骂、群体仇恨；诈骗诱导、非法交易招揽。须结合上下文与审核策略判定，不能仅按关键词拒绝。</p></details></div><footer><button class="btn primary" onclick="locateRisk('description','')">返回修改</button></footer></section>`};
function locateRisk(field,word){$('#audit')?.remove();const e=$('[name="'+field+'"]');if(e){e.classList.add('riskfield');e.focus();e.scrollIntoView({block:'center',behavior:'smooth'});if(word){const i=e.value.indexOf(word);if(i>=0)e.setSelectionRange(i,i+word.length)}e.addEventListener('input',()=>e.classList.remove('riskfield'),{once:true})}}
function previewRisk(){openForm();fillDemo();$('[name=description]').value='提供区域数据交换服务。敏感词测试。';$('#scenario').value='risk';auditScenario='risk';pending=Object.fromEntries(new FormData($('#registration')));showAudit('risk')}
function downloadRiskReport(){const text='内容安全审核结果（原型演示）\n机器审核未通过；申请未提交；未进入人工审核。\n风险位置：业务简介\n演示风险标记：敏感词测试\n请修改后重新提交。';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='机器审核结果-演示.txt';a.click();URL.revokeObjectURL(a.href)}
// Render after subsystem overrides; route shortcuts aid review without replacing the iframe.
if(new URLSearchParams(location.search).get('view'))section='review';render();if(new URLSearchParams(location.search).get('view')==='risk')previewRisk();
